package app.rwun;
import org.json.*;import java.time.*;import java.util.*;
/** Read-only compatibility schema for archived cycling data, not an active app feature. */
final class CyclingData {
 static final List<String> KINDS=List.of("Road","MTB","Indoor");
 static JSONArray rows(JSONObject d,String key){JSONArray a=d.optJSONArray(key);return a==null?new JSONArray():a;}
 static void validate(JSONObject d)throws Exception{
  for(String k:V1State.keys(d))if(!Set.of("rides","planned","active","undo","archivedRecordings").contains(k))throw new IllegalArgumentException("Unknown cycling field");
  for(String key:List.of("rides","planned"))if(d.has(key)&&d.optJSONArray(key)==null)throw new IllegalArgumentException("Invalid cycling list");Set<String> matches=new HashSet<>();for(String key:List.of("rides","planned")){JSONArray a=rows(d,key);if(a.length()>5000)throw new IllegalArgumentException("Archive cycling history before adding more");Set<String> ids=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);String id=r.getString("id");if(id.isEmpty()||id.length()>160||!ids.add(id)||!KINDS.contains(r.getString("kind")))throw new IllegalArgumentException("Invalid ride identity");LocalDate.parse(r.getString("date"));if(key.equals("rides")){V103Data.whole(r,"seconds",1,180000);if(!r.isNull("km")){double km=r.getDouble("km");if(!Double.isFinite(km)||km<=0||km>1000)throw new IllegalArgumentException("Check cycling distance");}V103Data.whole(r,"effort",0,10);V103Data.whole(r,"fatigue",1,5);V103Data.whole(r,"hr",0,249);if(!(r.get("pain") instanceof Boolean))throw new IllegalArgumentException("Invalid ride feedback");String route=r.optString("route");if(!route.isEmpty()&&!route.matches("route-[a-zA-Z0-9-]+\\.jsonl"))throw new IllegalArgumentException("Invalid cycling route");if(r.getString("source").length()>180)throw new IllegalArgumentException("Invalid ride source");String plan=r.optString("planned");if(!plan.isEmpty()&&!matches.add(plan))throw new IllegalArgumentException("A planned ride can match only one completed ride");}else{if(!id.matches("[a-zA-Z0-9-]{1,80}"))throw new IllegalArgumentException("Invalid planned ride identity");V103Data.whole(r,"minutes",5,720);V103Data.whole(r,"effort",1,10);}}}
  if(d.has("archivedRecordings")){JSONArray archive=d.getJSONArray("archivedRecordings");if(archive.length()>20)throw new IllegalArgumentException("Too many archived recordings");for(int i=0;i<archive.length();i++){JSONObject r=archive.getJSONObject(i);if(r.toString().length()>20000||r.optString("archiveType").length()>80)throw new IllegalArgumentException("Invalid archived recording");String route=r.optString("route");if(!route.isEmpty()&&!route.matches("route-[a-zA-Z0-9-]+\\.jsonl"))throw new IllegalArgumentException("Invalid archived route");}}
  if(d.has("active")){JSONObject a=d.getJSONObject("active");if(!a.getString("id").matches("[a-zA-Z0-9-]{1,80}")||!a.getString("kind").equals("Indoor"))throw new IllegalArgumentException("Invalid indoor ride");LocalDate.parse(a.getString("date"));V103Data.clock(a);}
  if(d.has("undo")){JSONObject u=d.getJSONObject("undo");if(u.getLong("expires")<0||u.toString().length()>20000)throw new IllegalArgumentException("Invalid cycling undo");JSONObject check=new JSONObject().put("rides",new JSONArray().put(u.getJSONObject("ride")));validate(check);}
 }
 static void sanitise(JSONObject d){d.remove("active");d.remove("undo");}
}
